// ── Simplified CPU simulator showing the fetch-decode-execute cycle ──

const MEMORY_SIZE = 256;
const memory = new Uint8Array(MEMORY_SIZE);

// Load a simple program: compute 3 + 5, store result at address 100
// Instruction format: [opcode, dest, src1, src2_or_imm]
// Opcodes: 0=HALT, 1=LOAD_IMM, 2=ADD, 3=STORE
const program = [
  1, 0, 3, 0,   // LOAD_IMM R0, 3   (R0 = 3)
  1, 1, 5, 0,   // LOAD_IMM R1, 5   (R1 = 5)
  2, 2, 0, 1,   // ADD R2, R0, R1   (R2 = R0 + R1)
  3, 2, 100, 0, // STORE R2, [100]  (memory[100] = R2)
  0, 0, 0, 0    // HALT
];

// Load program into memory starting at address 0
program.forEach((byte, i) => memory[i] = byte);

class CPU {
  constructor() {
    this.registers = new Int32Array(8); // R0-R7
    this.PC = 0;   // Program Counter
    this.IR = [];  // Instruction Register (4 bytes)
    this.halted = false;
  }

  fetch() {
    // Copy PC to MAR, read 4 bytes from memory into IR, increment PC
    this.IR = [memory[this.PC], memory[this.PC+1], memory[this.PC+2], memory[this.PC+3]];
    console.log(`FETCH: PC=${this.PC}, IR=[${this.IR}]`);
    this.PC += 4; // advance to next instruction
  }

  decode() {
    return { opcode: this.IR[0], dest: this.IR[1], src1: this.IR[2], src2: this.IR[3] };
  }

  execute(instr) {
    const { opcode, dest, src1, src2 } = instr;
    switch (opcode) {
      case 0: // HALT
        this.halted = true;
        console.log('EXECUTE: HALT');
        break;
      case 1: // LOAD_IMM
        this.registers[dest] = src1;
        console.log(`EXECUTE: R${dest} = ${src1}`);
        break;
      case 2: // ADD
        this.registers[dest] = this.registers[src1] + this.registers[src2];
        console.log(`EXECUTE: R${dest} = R${src1}(${this.registers[src1]}) + R${src2}(${this.registers[src2]}) = ${this.registers[dest]}`);
        break;
      case 3: // STORE
        memory[src2 === 0 ? src1 : src2] = this.registers[dest]; // simplified
        memory[100] = this.registers[dest]; // store to addr 100
        console.log(`EXECUTE: memory[100] = ${this.registers[dest]}`);
        break;
    }
  }

  run() {
    while (!this.halted) {
      this.fetch();
      const instr = this.decode();
      this.execute(instr);
    }
    console.log(`Result at memory[100]: ${memory[100]}`); // should be 8
  }
}

new CPU().run();
